PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS `raw_attractions` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`name` text(256) NOT NULL,
	`name_local` text(256),
	`description` text,
	`latitude` real,
	`longitude` real,
	`source_url` text(256),
	`city_name` text(256),
	`country_code` text(2) NOT NULL,
	`source` text(64) NOT NULL,
	`status` text DEFAULT 'pending' NOT NULL,
	`attraction_id` integer,
	`created_at` integer DEFAULT (unixepoch()) NOT NULL,
	`updated_at` integer,
	FOREIGN KEY (`attraction_id`) REFERENCES `attractions`(`id`) ON UPDATE no action ON DELETE set null
);
CREATE TABLE IF NOT EXISTS "itinerary_day_places" (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`itinerary_day_id` integer NOT NULL,
	`attraction_id` integer NOT NULL,
	`order` integer NOT NULL,
	FOREIGN KEY (`itinerary_day_id`) REFERENCES `itinerary_days`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`attraction_id`) REFERENCES `attractions`(`id`) ON UPDATE no action ON DELETE restrict,
	CONSTRAINT "itinerary_day_places_order_check" CHECK("itinerary_day_places"."order" >= 1)
);
CREATE TABLE IF NOT EXISTS "trip_destinations" (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`trip_id` integer NOT NULL,
	`country_code` text(2) NOT NULL,
	FOREIGN KEY (`trip_id`) REFERENCES `trips`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE IF NOT EXISTS "attractions" (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`name` text(256) NOT NULL,
	`name_local` text(256),
	`description` text,
	`address` text,
	`latitude` real,
	`longitude` real,
	`is_must_see` integer,
	`is_predefined` integer,
	`source_url` text(256),
	`city_id` integer NOT NULL,
	`country_code` text(2) NOT NULL,
	`created_at` integer DEFAULT (unixepoch()) NOT NULL,
	`updated_at` integer,
	`is_verified` integer DEFAULT false NOT NULL
);
CREATE TABLE IF NOT EXISTS "itinerary_days" (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`name` text(256) NOT NULL,
	`trip_id` integer NOT NULL,
	`day_number` integer NOT NULL,
	`created_at` integer DEFAULT (unixepoch()) NOT NULL,
	`updated_at` integer,
	FOREIGN KEY (`trip_id`) REFERENCES `trips`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "itinerary_days_day_number_check" CHECK("itinerary_days"."day_number" >= 1)
);
CREATE TABLE IF NOT EXISTS "trips" (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`name` text(256) NOT NULL,
	`start_date` integer,
	`end_date` integer,
	`created_at` integer DEFAULT (unixepoch()) NOT NULL,
	`updated_at` integer
);
CREATE TABLE IF NOT EXISTS "routes" (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`from_attraction_id` integer NOT NULL,
	`to_attraction_id` integer NOT NULL,
	`geo_json` text NOT NULL,
	`distance_m` real NOT NULL,
	`duration_s` real NOT NULL,
	`created_at` integer DEFAULT (unixepoch()) NOT NULL,
	FOREIGN KEY (`from_attraction_id`) REFERENCES `attractions`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`to_attraction_id`) REFERENCES `attractions`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "routes_no_self_reference_check" CHECK("routes"."from_attraction_id" != "routes"."to_attraction_id")
);
DELETE FROM sqlite_sequence;
CREATE INDEX `raw_attractions_status_idx` ON `raw_attractions` (`status`);
CREATE INDEX `raw_attractions_country_idx` ON `raw_attractions` (`country_code`);
CREATE INDEX `raw_attractions_source_url_idx` ON `raw_attractions` (`source_url`);
CREATE INDEX `raw_attractions_attraction_idx` ON `raw_attractions` (`attraction_id`);
CREATE INDEX `itinerary_day_places_day_idx` ON `itinerary_day_places` (`itinerary_day_id`);
CREATE UNIQUE INDEX `itinerary_day_places_unique_idx` ON `itinerary_day_places` (`itinerary_day_id`,`attraction_id`);
CREATE UNIQUE INDEX `itinerary_day_places_order_unique_idx` ON `itinerary_day_places` (`itinerary_day_id`,`order`);
CREATE INDEX `trip_destinations_trip_idx` ON `trip_destinations` (`trip_id`);
CREATE UNIQUE INDEX `trip_destinations_unique_idx` ON `trip_destinations` (`trip_id`,`country_code`);
CREATE INDEX `attractions_city_idx` ON `attractions` (`city_id`);
CREATE INDEX `attractions_coords_idx` ON `attractions` (`latitude`,`longitude`);
CREATE INDEX `itinerary_days_trip_idx` ON `itinerary_days` (`trip_id`);
CREATE UNIQUE INDEX `itinerary_days_trip_day_unique_idx` ON `itinerary_days` (`trip_id`,`day_number`);
CREATE INDEX `trips_start_date_idx` ON `trips` (`start_date`);
CREATE INDEX `trips_end_date_idx` ON `trips` (`end_date`);
CREATE INDEX `trips_name_idx` ON `trips` (`name`);
CREATE UNIQUE INDEX `routes_unique_idx` ON `routes` (`from_attraction_id`,`to_attraction_id`);
CREATE INDEX `routes_from_attraction_idx` ON `routes` (`from_attraction_id`);
CREATE INDEX `routes_to_attraction_idx` ON `routes` (`to_attraction_id`);
COMMIT;
